PRAGMA foreign_keys = ON;
CREATE TABLE ingestion_runs (run_id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL CHECK(dataset_id IN ('94025','28567','11406','11586')), source_id TEXT NOT NULL, resource_id TEXT NOT NULL, execution_mode TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','succeeded','failed','cancelled')), started_at TEXT NOT NULL, completed_at TEXT, adapter_version TEXT NOT NULL, raw_schema_version TEXT NOT NULL, domain_schema_version TEXT NOT NULL, fetched_at TEXT, http_status INTEGER, content_type TEXT, response_hash TEXT, response_bytes INTEGER CHECK(response_bytes IS NULL OR response_bytes >= 0), raw_row_count INTEGER CHECK(raw_row_count IS NULL OR raw_row_count >= 0), normalized_record_count INTEGER CHECK(normalized_record_count IS NULL OR normalized_record_count >= 0), rejected_record_count INTEGER CHECK(rejected_record_count IS NULL OR rejected_record_count >= 0), warning_count INTEGER CHECK(warning_count IS NULL OR warning_count >= 0), failure_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE source_snapshots (snapshot_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES ingestion_runs(run_id) ON DELETE CASCADE, dataset_id TEXT NOT NULL CHECK(dataset_id IN ('94025','28567','11406','11586')), source_id TEXT NOT NULL, resource_id TEXT NOT NULL, adapter_version TEXT NOT NULL, raw_schema_version TEXT NOT NULL, domain_schema_version TEXT NOT NULL, fetched_at TEXT NOT NULL, response_hash TEXT NOT NULL, response_bytes INTEGER NOT NULL CHECK(response_bytes >= 0), raw_row_count INTEGER NOT NULL CHECK(raw_row_count >= 0), accepted_record_count INTEGER NOT NULL CHECK(accepted_record_count >= 0), rejected_record_count INTEGER NOT NULL CHECK(rejected_record_count >= 0), warning_count INTEGER NOT NULL CHECK(warning_count >= 0), validation_status TEXT NOT NULL CHECK(validation_status IN ('valid','valid_with_warnings','invalid')), publication_eligibility INTEGER NOT NULL CHECK(publication_eligibility IN (0,1)), revenue_year_month TEXT, created_at TEXT NOT NULL);
CREATE TABLE published_snapshot_pointers (dataset_id TEXT PRIMARY KEY CHECK(dataset_id IN ('94025','28567','11406','11586')), source_id TEXT NOT NULL, resource_id TEXT NOT NULL, current_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id), previous_snapshot_id TEXT REFERENCES source_snapshots(snapshot_id), publication_run_id TEXT NOT NULL REFERENCES ingestion_runs(run_id), published_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 1));
CREATE TABLE source_health (source_id TEXT NOT NULL, resource_id TEXT NOT NULL, last_attempt_at TEXT, last_successful_fetch_at TEXT, last_successful_publish_at TEXT, consecutive_failure_count INTEGER NOT NULL CHECK(consecutive_failure_count >= 0), last_failure_code TEXT, status TEXT NOT NULL CHECK(status IN ('unknown','healthy','degraded','failing','suspended')), updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 1), PRIMARY KEY(source_id, resource_id));
CREATE INDEX idx_runs_dataset_status ON ingestion_runs(dataset_id,status); CREATE INDEX idx_runs_source_resource ON ingestion_runs(source_id,resource_id); CREATE INDEX idx_snapshots_run ON source_snapshots(run_id); CREATE INDEX idx_snapshots_dataset_created ON source_snapshots(dataset_id,created_at); CREATE INDEX idx_snapshots_dataset_month ON source_snapshots(dataset_id,revenue_year_month); CREATE INDEX idx_snapshots_hash ON source_snapshots(response_hash); CREATE INDEX idx_pointers_current ON published_snapshot_pointers(current_snapshot_id); CREATE INDEX idx_health_status ON source_health(status,updated_at);
